var a=`1034-che-ba-mau`;var n=`world-1034`;var t=`VN`;var s=`southeast-asia`;var r=8;var l=673;var o={en:`Che Ba Mau`,ua:`Че ба мау`};var m={en:`Che Ba Mau is a dish from Vietnam prepared with mung beans, adzuki beans, tapioca pearls, coconut milk. This is a home-scale version with measured ingredients in the individual steps where they are used. The three-color dessert is an accessible approximation with available beans and tapioca, not a full traditional jelly selection.`,ua:`Че ба мау, страва кухні країни В'єтнам, яку готують із таких продуктів: маш, квасоля адзукі, кульки тапіоки, кокосове молоко. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Триколірний десерт спрощено з доступних бобів і тапіоки, без традиційного набору желе.`};var u=[{en:`Soak the dried mung beans in clean water, discard the water and simmer separately in fresh water until fully soft.`,ua:`Замочіть сухий маш у чистій воді, злийте її й окремо зваріть у свіжій воді до м’якості.`,t:[`soaking-legumes`],m:210,i:[[`mung-beans`,170,`g`],[`water`,600,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 45 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 45 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:45,i:[[`water`,650,`ml`]]},{en:`Soak the adzuki beans for several hours; discard the soaking water before fully boiling until tender.`,ua:`Замочіть боби адзукі на кілька годин; злийте воду від замочування перед варінням до м’якості.`,t:[`soaking-legumes`],m:320,i:[[`adzuki-beans`,150,`g`],[`water`,550,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 75 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 75 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:75,i:[[`water`,700,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 13 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 13 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:13,i:[[`tapioca-pearls`,110,`g`],[`water`,550,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`coconut-milk`,400,`ml`],[`palm-sugar`,105,`g`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:4,i:[[`ice-cubes`,350,`g`],[`pandan-leaves`,3,`ml`]]}];var d={slug:a,id:n,country:`VN`,region:s,servings:8,minutes:673,title:o,text:m,steps:u};export{t as country,d as default,n as id,l as minutes,s as region,r as servings,a as slug,u as steps,m as text,o as title};